/**
 * Unit tests for workflow-agenttype-advisor PreToolUse[Workflow] hook (M170/#3126)
 *
 * The advisor nudges inline Workflow scripts whose agent() stages are all
 * untyped toward the specialist catalog. Advisory only — every path must
 * return continue:true / permissionDecision allow-or-absent.
 */

import { describe, expect, test } from 'vitest';
import type { HookInput } from '../../types.js';
import {
  countAgentCalls,
  workflowAgentTypeAdvisor,
} from '../../pretool/task/workflow-agenttype-advisor.js';

function makeInput(toolInput: Record<string, unknown>, toolName = 'Workflow'): HookInput {
  return {
    tool_name: toolName,
    session_id: 'session-wf-advisor',
    tool_input: toolInput,
  };
}

function contextOf(result: ReturnType<typeof workflowAgentTypeAdvisor>): string {
  return (result.hookSpecificOutput?.additionalContext as string) || '';
}

const UNTYPED_SCRIPT = `
export const meta = { name: 'x', description: 'y' }
const a = await agent('review the diff', { schema: S })
const b = await parallel(items.map(i => () => agent('verify ' + i.title)))
return { a, b }
`;

const TYPED_SCRIPT = `
export const meta = { name: 'x', description: 'y' }
const a = await agent('review the diff', { agentType: 'ork:code-quality-reviewer' })
const b = await agent('glue stage')
return { a, b }
`;

describe('countAgentCalls', () => {
  test('counts bare agent( call sites', () => {
    expect(countAgentCalls(UNTYPED_SCRIPT)).toBe(2);
  });

  test('ignores member calls and identifiers containing agent', () => {
    const script = `
const x = subagent(1)
foo.agent(2)
const myagent = () => 0
agent('real one')
`;
    expect(countAgentCalls(script)).toBe(1);
  });

  test('returns 0 for scripts without agent calls', () => {
    expect(countAgentCalls('const x = 1; log("no spawns")')).toBe(0);
  });
});

describe('workflowAgentTypeAdvisor', () => {
  test('nudges when all agent() stages are untyped', () => {
    const result = workflowAgentTypeAdvisor(makeInput({ script: UNTYPED_SCRIPT }));
    expect(result.continue).toBe(true);
    expect(result.hookSpecificOutput?.permissionDecision).toBe('allow');
    const ctx = contextOf(result);
    expect(ctx).toContain('2 agent() stage(s), none typed');
    expect(ctx).toContain('ork:security-auditor');
    expect(ctx).toContain('ork:test-generator');
    expect(ctx).toContain('omit agentType');
  });

  test('stays silent when at least one stage is typed', () => {
    const result = workflowAgentTypeAdvisor(makeInput({ script: TYPED_SCRIPT }));
    expect(result.continue).toBe(true);
    expect(contextOf(result)).toBe('');
  });

  test('stays silent for scripts with no agent() calls', () => {
    const result = workflowAgentTypeAdvisor(makeInput({ script: 'log("hi"); return 1' }));
    expect(contextOf(result)).toBe('');
  });

  test('stays silent for named/scriptPath runs (no inline script)', () => {
    expect(contextOf(workflowAgentTypeAdvisor(makeInput({ name: 'review-changes' })))).toBe('');
    expect(contextOf(workflowAgentTypeAdvisor(makeInput({ scriptPath: '/tmp/x.mjs' })))).toBe('');
  });

  test('stays silent for non-Workflow tools', () => {
    const result = workflowAgentTypeAdvisor(makeInput({ script: UNTYPED_SCRIPT }, 'Agent'));
    expect(contextOf(result)).toBe('');
  });

  test('never blocks: advisory path keeps continue:true and allow decision', () => {
    for (const toolInput of [{ script: UNTYPED_SCRIPT }, { script: TYPED_SCRIPT }, {}]) {
      const result = workflowAgentTypeAdvisor(makeInput(toolInput));
      expect(result.continue).toBe(true);
      const decision = result.hookSpecificOutput?.permissionDecision;
      expect(decision === undefined || decision === 'allow').toBe(true);
    }
  });
});
